import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdminListAluno = () => {
  const [alunos, setAlunos] = useState([
    "Pedro Ferreira",
    "Leandro Silva",
    "Marcos Pedro",
    "Antonio Geral",
    "Carlos Paulo",
    "Ana Catarina",
  ]);

  const [novoAluno, setNovoAluno] = useState("");

  const adicionarAluno = () => {
    if (novoAluno.trim()) {
      setAlunos([...alunos, novoAluno]);
      setNovoAluno("");
    }
  };

  const removerAluno = (index) => {
    setAlunos(alunos.filter((_, i) => i !== index));
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="mt-3">
        <h3>Alunos</h3>
        <div className="d-flex mb-3">
          <input
            type="text"
            className="form-control me-2"
            placeholder="busque aluno pelo nome"
            value={novoAluno}
            onChange={(e) => setNovoAluno(e.target.value)}
          />
          <button className="btn btn-primary" onClick={adicionarAluno}>
            Adicionar
          </button>
        </div>

        <ul className="list-group">
          {alunos.map((aluno, index) => (
            <li
              key={index}
              className="list-group-item d-flex justify-content-between align-items-center"
            >
              {aluno}
              <div>
                <button className="btn btn-outline-primary btn-sm mx-2">
                  ✏️
                </button>
                <button
                  className="btn btn-outline-danger btn-sm"
                  onClick={() => removerAluno(index)}
                >
                  🗑️
                </button>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default AdminListAluno;
